// NOTE: The CSV fixtures consumed by these tests (test_data/pivot_hl/output_*.csv)
// were generated by a Python script using pandas to compute reference pivot levels from input_data2.csv.

func TestPivotHLDefault(t *testing.T) {
	candles, _ := readCandles("test_data/input_data2.csv")
	expected, _ := readData("test_data/pivot_hl/output_default.csv", []int{1, 2, 3}, 4)
	indicator, _ := talive.NewPivotHL(10, 10)
	result := make([][]float64, 3)
	for i := range result {
		result[i] = make([]float64, len(candles))
	}
	for i, candle := range candles {
		res := indicator.Next(candle)
		for j := 0; j < 3; j++ {
			result[j][i] = roundFloat(res[j], 4)
		}
	}
	labels := []string{"PivotHigh", "PivotLow", "Event"}
	for j, label := range labels {
		if !reflect.DeepEqual(result[j], expected[j]) {
			t.Fatalf("[PivotHL 10/10] %s mismatch %v", label, difference(result[j], expected[j]))
		}
	}
}

